def transform(g):
    a=np.array([r[:] for r in g])
    cols=[c for c in np.unique(a) if c!=0]
    sh={c:cells_of(a,c) for c in cols}
    t=max(sh,key=lambda c:len(sh[c])); o=[c for c in sh if c!=t][0]
    for i,j in sh[o]: a[i,j]=0
    cs=sh[t]
    r0,r1=min(i for i,j in cs),max(i for i,j in cs)
    c0,c1=min(j for i,j in cs),max(j for i,j in cs)
    sc=sh[o]
    sr0=min(i for i,j in sc); sc0=min(j for i,j in sc)
    H=r1-r0+1; W=c1-c0+1
    if W>=H:
        below = sr0 > r1
        for i,j in cs:
            a[2*r1+1-i if below else i-(H+1), j]=t
    else:
        right = sc0 > c1
        for i,j in cs:
            a[i, 2*c1+1-j if right else j-(W+1)]=t
    return a.tolist()
